def refuse_duplicate_titles(apps, schema_editor):
    """The new rule (one live title per seller, ignoring case) cannot be added while the
    data already breaks it. Stop with a clear list instead of a database error."""
    Listing = apps.get_model("catalog", "Listing")
    seen, clashes = {}, []
    for listing_id, seller_id, title in Listing._base_manager.filter(
        deleted_at__isnull=True, seller__isnull=False
    ).values_list("id", "seller_id", "title").order_by("id"):
        key = (seller_id, title.strip().lower())
        if key in seen:
            clashes.append(f"seller {seller_id}: listings {seen[key]} and {listing_id} (\"{title}\")")
        else:
            seen[key] = listing_id
    if clashes:
        raise RuntimeError(
            "Cannot add the unique-title rule: these sellers already have two live listings with the same "
            "title. Rename or delete one of each pair, then run the migration again:\n  " + "\n  ".join(clashes)
        )


def backfill_requested_at(apps, schema_editor):
    """Listings already waiting for review get their creation time as the request time."""
